<?php
$trip=trip_by_id((int)($_GET['trip']??$_SESSION['trip_id']??0)); if(!$trip){ echo '<section class="container content-section"><div class="empty-state"><h2>Choose a train first</h2><a class="button primary" href="?page=search">Search journeys</a></div></section>'; return; }
$_SESSION['trip_id']=(int)$trip['id']; $q=db()->prepare('SELECT * FROM trip_seats WHERE trip_id=? ORDER BY seat_code');$q->execute([$trip['id']]);$seatRows=$q->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$chosen=array_values(array_unique(array_filter($_POST['seats']??[],fn($x)=>preg_match('/^[A-D][0-9]{2}$/',(string)$x)))); if(!$chosen || count($chosen)>6){flash('Select between one and six seats.','error');}else{$in=implode(',',array_fill(0,count($chosen),'?'));$check=db()->prepare("SELECT COUNT(*) FROM trip_seats WHERE trip_id=? AND status='available' AND seat_code IN ($in)");$check->execute(array_merge([$trip['id']],$chosen));if((int)$check->fetchColumn()!==count($chosen)){flash('One or more seats are no longer available. Please choose again.','error');}else{$_SESSION['chosen_seats']=$chosen;$_SESSION['trip_id']=(int)$trip['id'];header('Location: ?page=passenger');exit;}}}
?>
<section class="page-banner"><div class="container"><p class="eyebrow">STEP 1 OF 3 · YOUR JOURNEY</p><h1>Pick your <em>place.</em></h1><p><?= h($trip['origin']) ?> to <?= h($trip['destination']) ?> · <?= h(date('D, d M',strtotime($trip['depart_at']))) ?> · <?= h($trip['train_code']) ?></p></div></section><section class="container content-section"><div class="seat-layout"><div class="coach-card"><div class="coach-top"><strong>Coach A · Standard</strong><span>Front of train ⌃</span></div><form method="post"><?= csrf_field() ?><div class="seat-grid"><?php foreach($seatRows as $i=>$seat): if($i%4===0): ?><span class="row-num"><?= (int)($i/4)+1 ?></span><?php endif; ?><label class="seat <?= $seat['status']==='available'?'':'unavailable' ?>"><input type="checkbox" name="seats[]" value="<?= h($seat['seat_code']) ?>" <?= $seat['status']==='available'?'':'disabled' ?>><span><?= h(substr($seat['seat_code'],1)) ?></span></label><?php if($i%4===1): ?><span class="aisle"></span><?php endif; ?><?php endforeach; ?></div><div class="seat-legend"><span><i class="available-key"></i>Available</span><span><i class="selected-key"></i>Selected</span><span><i class="taken-key"></i>Unavailable</span></div><div class="coach-bottom">🚆 &nbsp; Coach A · 20 seats</div><button class="button primary full-width">Continue with seats <span>→</span></button></form></div><aside class="journey-summary"><p class="eyebrow">JOURNEY SUMMARY</p><h3><?= h($trip['origin']) ?> <span>→</span> <?= h($trip['destination']) ?></h3><p><?= h($trip['train_code']) ?> · <?= h(date('d M Y',strtotime($trip['depart_at']))) ?></p><div class="summary-line"><span>Departure</span><strong><?= h(date('H:i',strtotime($trip['depart_at']))) ?></strong></div><div class="summary-line"><span>From</span><strong><?= h($trip['origin']) ?></strong></div><div class="summary-line"><span>Base fare / seat</span><strong><?= money((float)$trip['base_fare']) ?></strong></div><small>Choose up to 6 available seats. Seats are confirmed at booking.</small></aside></div></section>
